rotect_objects_delete BEFORE DELETE ON storage.objects FOR EACH STATEMENT EXECUTE FUNCTION storage.protect_delete()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n","name":"protect_objects_delete","table":"storage.objects"},{"definition":"CREATE TRIGGER update_objects_updated_at BEFORE UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.update_updated_at_column()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION storage.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n$function$\n","name":"update_objects_updated_at","table":"storage.objects"},{"definition":"CREATE TRIGGER source_bindings_immutable BEFORE DELETE OR UPDATE ON public.upload_source_bindings FOR EACH ROW EXECUTE FUNCTION protect_bound_source_review_v1()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION public.protect_bound_source_review_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF TG_TABLE_NAME='upload_source_bindings' THEN\n    RAISE EXCEPTION 'Source bindings are fixed; prepare a separately reviewed job';\n  END IF;\n  IF OLD.source_semantics->>'source_key' IN ('syracuse_code_violations_v2','chicago_22u3_xenr') THEN\n    RAISE EXCEPTION 'Source review staging is immutable; prepare a new observation or revision';\n  END IF;\n  IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND $function$\n","name":"source_bindings_immutable","table":"upload_source_bindings"}]}$expected$::jsonb;

 a:=a-ARRAY['observed_at','current_user','session_user','search_path','server_version','default_acl'];
 e:=e-ARRAY['observed_at','current_user','session_user','search_path','server_version','default_acl'];
 IF a ? 'roles' THEN
  a:=jsonb_set(a,'{roles}',coalesce((SELECT jsonb_agg(item) FROM jsonb_array_elements(a->'roles') q(item) WHERE item->>'name' IN ('anon','authenticated','service_role')),'[]'));
 END IF;
 IF a ? 'memberships' THEN
  a:=jsonb_set(a,'{memberships}',coalesce((SELECT jsonb_agg(item) FROM jsonb_array_elements(coalesce(nullif(a->'memberships','null'::jsonb),'[]')) q(item) WHERE item->>'member' IN ('anon','authenticated','service_role')),'[]'));
 END IF;
 -- Only array ordering is normalized; within-table column order and enum order stay pinned.
 FOREACH side IN ARRAY ARRAY['actual','expected'] LOOP
  target:=CASE WHEN side='actual' THEN a ELSE e END;
  FOR k,v IN SELECT key,value FROM jsonb_each(target) LOOP
   IF jsonb_typeof(v)='array' AND k<>'enum_labels' THEN
    IF k IN ('columns','generated_columns') THEN
     SELECT coalesce(jsonb_agg(item ORDER BY coalesce(item->>'table',''),ordinal),'[]') INTO sorted FROM jsonb_array_elements(v) WITH ORDINALITY q(item,ordinal);
    ELSE
     SELECT coalesce(jsonb_agg(item ORDER BY item),'[]') INTO sorted FROM jsonb_array_elements(v) item;
    END IF;
    target:=jsonb_set(target,ARRAY[k],sorted);
   END IF;
  END LOOP;
  IF side='actual' THEN a:=target;ELSE e:=target;END IF;
 END LOOP;
 IF a IS DISTINCT FROM e THEN
  SELECT key INTO k FROM jsonb_each(e) WHERE a->key IS DISTINCT FROM e->key ORDER BY key LIMIT 1;
  RAISE EXCEPTION 'original_intake_catalog_drift:%:%:%','before','base',k USING ERRCODE='55000';END IF;
END $guard$;

DO $guard$ DECLARE a jsonb;e jsonb;target jsonb;sorted jsonb;k text;v jsonb;side text;BEGIN
