-- LOCAL CANDIDATE. Not a production migration or an activation setting.
-- Reuses upload_jobs and csv-uploads. No existing job, source, policy or role is rewritten.
-- Exact native prerequisite/Storage policy pins must be supplied before installation.
SET LOCAL search_path=pg_catalog;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

CREATE TABLE snap_relaunch.original_intake_reservations_v1 (
 job_id uuid PRIMARY KEY REFERENCES public.upload_jobs(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 owner_id uuid NOT NULL,
 original_sha256 text NOT NULL CHECK(original_sha256 ~ '^[a-f0-9]{64}$'),
 original_bytes bigint NOT NULL CHECK(original_bytes BETWEEN 1 AND 15728640),
 original_filename text NOT NULL CHECK(length(original_filename) BETWEEN 1 AND 240),
 object_key text NOT NULL UNIQUE,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(owner_id,original_sha256),
 CHECK(object_key='_snap_originals/v1/'||owner_id::text||'/'||job_id::text||'/'||original_sha256||'.csv')
);
CREATE TABLE snap_relaunch.original_intake_requests_v1 (
 owner_id uuid NOT NULL, request_id uuid NOT NULL,
 job_id uuid NOT NULL REFERENCES snap_relaunch.original_intake_reservations_v1(job_id),
 original_filename text NOT NULL CHECK(length(original_filename) BETWEEN 1 AND 240),
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,request_id)
);
CREATE TABLE snap_relaunch.original_intake_verifications_v1 (
 job_id uuid PRIMARY KEY REFERENCES snap_relaunch.original_intake_reservations_v1(job_id),
 verification_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
 original_sha256 text NOT NULL CHECK(original_sha256 ~ '^[a-f0-9]{64}$'),
 original_bytes bigint NOT NULL CHECK(original_bytes BETWEEN 1 AND 15728640),
 verified_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE snap_relaunch.original_intake_revocations_v1 (
 job_id uuid PRIMARY KEY REFERENCES snap_relaunch.original_intake_reservations_v1(job_id),
 revocation_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
 owner_id uuid NOT NULL, reason text NOT NULL CHECK(reason='owner_requested_hold'),
 created_at timestamptz NOT NULL DEFAULT now()
);

CREATE FUNCTION snap_relaunch.original_intake_writes_enabled_v1()
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT false$$;

CREATE FUNCTION snap_relaunch.original_intake_actor_v1(p_owner uuid)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF p_owner IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p_owner
  AND u.deleted_at IS NULL AND u.is_anonymous IS FALSE
  AND (u.banned_until IS NULL OR u.banned_until<=now())
  AND ((u.email_confirmed_at IS NOT NULL AND u.email_confirmed_at<=now())
   OR (u.phone_confirmed_at IS NOT NULL AND u.phone_confirmed_at<=now()))) THEN
  RAISE EXCEPTION 'original_intake_owner_unavailable' USING ERRCODE='42501';
 END IF;
END$$;

CREATE FUNCTION snap_relaunch.original_intake_result_v1(p_owner uuid,p_job uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('version','original-intake-v1','owner_id',r.owner_id,'job_id',r.job_id,
  'original_sha256',r.original_sha256,'original_bytes',r.original_bytes,'original_filename',r.original_filename,
  'bucket','csv-uploads','object_key',r.object_key,'created_at',r.created_at,
  'state',CASE WHEN x.job_id IS NOT NULL THEN 'revoked' WHEN v.job_id IS NOT NULL THEN 'original_verified' ELSE 'reserved' END,
  'verification_id',v.verification_id,'verified_at',v.verified_at,'revocation_id',x.revocation_id,
  'intake_enabled',snap_relaunch.original_intake_writes_enabled_v1(),'source_classification','unclassified','processing_authorized',false,'customer_accepted',false)
 FROM snap_relaunch.original_intake_reservations_v1 r
 LEFT JOIN snap_relaunch.original_intake_verifications_v1 v ON v.job_id=r.job_id
 LEFT JOIN snap_relaunch.original_intake_revocations_v1 x ON x.job_id=r.job_id
 WHERE r.owner_id=p_owner AND r.job_id=p_job
$$;

CREATE FUNCTION public.fn_reserve_original_intake_v1(p_request_id uuid,p_sha256 text,p_bytes bigint,p_filename text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor uuid:=auth.uid(); r snap_relaunch.original_intake_reservations_v1%ROWTYPE;
 prior_job uuid; proposed_job uuid; proposed_key text;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'original_intake_read_committed_required' USING ERRCODE='25001';END IF;
 PERFORM snap_relaunch.original_intake_actor_v1(actor);
 IF NOT snap_relaunch.original_intake_writes_enabled_v1() THEN RAISE EXCEPTION 'original_intake_held' USING ERRCODE='55000';END IF;
 IF p_request_id IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[a-f0-9]{64}$'
  OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 15728640 OR p_filename IS NULL
  OR length(p_filename) NOT BETWEEN 1 AND 240 OR p_filename ~ '[[:cntrl:]]' OR lower(p_filename) !~ '\.csv$' THEN
  RAISE EXCEPTION 'original_intake_invalid_binding' USING ERRCODE='22023';END IF;
 -- The same owner lock is first for reservation, verification and revocation.
 PERFORM pg_advisory_xact_lock(928411,hashtext(actor::text));
 SELECT job_id INTO prior_job FROM snap_relaunch.original_intake_requests_v1 WHERE owner_id=actor AND request_id=p_request_id;
 IF prior_job IS NOT NULL THEN
  SELECT * INTO STRICT r FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=prior_job;
  IF r.owner_id<>actor OR r.original_sha256<>p_sha256 OR r.original_bytes<>p_bytes THEN
   RAISE EXCEPTION 'original_intake_request_conflict' USING ERRCODE='22023';END IF;
 ELSE
  SELECT * INTO r FROM snap_relaunch.original_intake_reservations_v1 WHERE owner_id=actor AND original_sha256=p_sha256;
  IF FOUND AND r.original_bytes<>p_bytes THEN RAISE EXCEPTION 'original_intake_digest_conflict' USING ERRCODE='22023';END IF;
  IF NOT FOUND THEN
   proposed_job:=gen_random_uuid();proposed_key:='_snap_originals/v1/'||actor::text||'/'||proposed_job::text||'/'||p_sha256||'.csv';
   -- The private reservation precedes the job within this transaction. Its FK is deferred.
   -- The job trigger accepts only this immutable private witness, never a caller GUC.
   INSERT INTO snap_relaunch.original_intake_reservations_v1(job_id,owner_id,original_sha256,original_bytes,original_filename,object_key)
   VALUES(proposed_job,actor,p_sha256,p_bytes,p_filename,proposed_key) RETURNING * INTO r;
   INSERT INTO public.upload_jobs(id,user_id,filename,file_size,storage_path,status,city,county,state,scope,source_type,warnings)
   VALUES(proposed_job,actor,p_filename,p_bytes,proposed_key,'QUEUED',NULL,NULL,NULL,NULL,NULL,
    '["Original reservation only. File presence, source classification and processing are not yet confirmed."]'::jsonb);
  END IF;
  INSERT INTO snap_relaunch.original_intake_requests_v1(owner_id,request_id,job_id,original_filename)
  VALUES(actor,p_request_id,r.job_id,p_filename);
 END IF;
 RETURN snap_relaunch.original_intake_result_v1(actor,r.job_id);
END$$;

CREATE FUNCTION public.fn_lookup_original_intake_v1(p_sha256 text,p_bytes bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor uuid:=auth.uid();r snap_relaunch.original_intake_reservations_v1%ROWTYPE;
BEGIN
 PERFORM snap_relaunch.original_intake_actor_v1(actor);
 IF p_sha256 IS NULL OR p_sha256 !~ '^[a-f0-9]{64}$' OR p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND 15728640 THEN
  RAISE EXCEPTION 'original_intake_invalid_binding' USING ERRCODE='22023';END IF;
 SELECT * INTO r FROM snap_relaunch.original_intake_reservations_v1 WHERE owner_id=actor AND original_sha256=p_sha256;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF r.original_bytes<>p_bytes THEN RAISE EXCEPTION 'original_intake_digest_conflict' USING ERRCODE='22023';END IF;
 RETURN snap_relaunch.original_intake_result_v1(actor,r.job_id);
END$$;

CREATE FUNCTION public.fn_read_original_intake_v1(p_job uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor uuid:=auth.uid(); result jsonb;
BEGIN
 PERFORM snap_relaunch.original_intake_actor_v1(actor);
 result:=snap_relaunch.original_intake_result_v1(actor,p_job);
 IF result IS NULL THEN RAISE EXCEPTION 'original_intake_unavailable' USING ERRCODE='42501';END IF;
 RETURN result;
END$$;

CREATE FUNCTION public.fn_revoke_original_intake_v1(p_job uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor uuid:=auth.uid();
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'original_intake_read_committed_required' USING ERRCODE='25001';END IF;
 PERFORM snap_relaunch.original_intake_actor_v1(actor);
 PERFORM pg_advisory_xact_lock(928411,hashtext(actor::text));
 IF NOT EXISTS(SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=p_job AND owner_id=actor) THEN
  RAISE EXCEPTION 'original_intake_unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO snap_relaunch.original_intake_revocations_v1(job_id,owner_id,reason) VALUES(p_job,actor,'owner_requested_hold') ON CONFLICT(job_id) DO NOTHING;
 RETURN snap_relaunch.original_intake_result_v1(actor,p_job);
END$$;

-- Exact service-only proof reader. It never accepts a user-supplied owner as authority.
-- The endpoint must first validate the live user and pass that verified ID.
CREATE FUNCTION public.fn_original_intake_transport_read_v1(p_owner uuid,p_job uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'original_intake_service_required' USING ERRCODE='42501';END IF;
 PERFORM snap_relaunch.original_intake_actor_v1(p_owner);
 result:=snap_relaunch.original_intake_result_v1(p_owner,p_job);
 IF result IS NULL THEN RAISE EXCEPTION 'original_intake_unavailable' USING ERRCODE='42501';END IF;
 RETURN result;
END$$;

CREATE FUNCTION public.fn_verify_original_intake_v1(p_owner uuid,p_job uuid,p_sha256 text,p_bytes bigint,p_object_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r snap_relaunch.original_intake_reservations_v1%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'original_intake_read_committed_required' USING ERRCODE='25001';END IF;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'original_intake_service_required' USING ERRCODE='42501';END IF;
 PERFORM snap_relaunch.original_intake_actor_v1(p_owner);
 IF NOT snap_relaunch.original_intake_writes_enabled_v1() THEN RAISE EXCEPTION 'original_intake_held' USING ERRCODE='55000';END IF;
 PERFORM pg_advisory_xact_lock(928411,hashtext(p_owner::text));
 SELECT * INTO r FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=p_job AND owner_id=p_owner;
 IF NOT FOUND OR r.original_sha256 IS DISTINCT FROM p_sha256 OR r.original_bytes IS DISTINCT FROM p_bytes
  OR r.object_key IS DISTINCT FROM p_object_key THEN RAISE EXCEPTION 'original_intake_proof_conflict' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM snap_relaunch.original_intake_revocations_v1 WHERE job_id=p_job) THEN
  RAISE EXCEPTION 'original_intake_revoked' USING ERRCODE='55000';END IF;
 INSERT INTO snap_relaunch.original_intake_verifications_v1(job_id,original_sha256,original_bytes)
 VALUES(p_job,p_sha256,p_bytes) ON CONFLICT(job_id) DO NOTHING;
 RETURN snap_relaunch.original_intake_result_v1(p_owner,p_job);
END$$;

CREATE FUNCTION public.fn_original_intake_delete_guard_v1(p_job uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM snap_relaunch.original_intake_actor_v1(auth.uid());
 IF NOT EXISTS(SELECT 1 FROM public.upload_jobs j WHERE j.id=p_job AND (j.user_id=auth.uid()
  OR coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false))) THEN
  RAISE EXCEPTION 'original_intake_unavailable' USING ERRCODE='42501';END IF;
 RETURN EXISTS(SELECT 1 FROM public.upload_jobs j WHERE j.id=p_job AND starts_with(j.storage_path,'_snap_originals/v1/'))
  OR EXISTS(SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=p_job);
END$$;

CREATE FUNCTION snap_relaunch.original_intake_immutable_v1()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'original_intake_history_immutable' USING ERRCODE='55000';END$$;

CREATE FUNCTION snap_relaunch.original_intake_job_guard_v1()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF starts_with(NEW.storage_path,'_snap_originals/v1/') AND NOT EXISTS(
   SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 r WHERE r.job_id=NEW.id AND r.owner_id=NEW.user_id
    AND r.original_filename=NEW.filename AND r.original_bytes=NEW.file_size AND r.object_key=NEW.storage_path) THEN
   RAISE EXCEPTION 'original_intake_reserved_path' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND starts_with(NEW.storage_path,'_snap_originals/v1/') AND NEW.storage_path IS DISTINCT FROM OLD.storage_path THEN
  RAISE EXCEPTION 'original_intake_identity_immutable' USING ERRCODE='55000';END IF;
 IF starts_with(OLD.storage_path,'_snap_originals/v1/') OR EXISTS(SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=OLD.id) THEN
  IF TG_OP='DELETE' OR NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id
   OR NEW.storage_path IS DISTINCT FROM OLD.storage_path OR NEW.filename IS DISTINCT FROM OLD.filename
   OR NEW.file_size IS DISTINCT FROM OLD.file_size THEN RAISE EXCEPTION 'original_intake_identity_immutable' USING ERRCODE='55000';END IF;
  IF current_setting('role',true) IN ('anon','authenticated') THEN
   RAISE EXCEPTION 'original_intake_processing_held' USING ERRCODE='55000';END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER original_intake_job_guard_v1 BEFORE INSERT OR UPDATE OR DELETE ON public.upload_jobs
FOR EACH ROW EXECUTE FUNCTION snap_relaunch.original_intake_job_guard_v1();

DO $private$ DECLARE t text; f regprocedure; role_name text; g record; BEGIN
 FOREACH t IN ARRAY ARRAY['original_intake_reservations_v1','original_intake_requests_v1','original_intake_verifications_v1','original_intake_revocations_v1'] LOOP
  EXECUTE format('ALTER TABLE snap_relaunch.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE TRIGGER original_intake_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON snap_relaunch.%I FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.original_intake_immutable_v1()',t);
  FOR g IN SELECT a.grantee FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=('snap_relaunch.'||t)::regclass AND a.grantee<>c.relowner LOOP
   role_name:=CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(g.grantee)) END;
   EXECUTE format('REVOKE ALL ON TABLE snap_relaunch.%I FROM %s',t,role_name);
  END LOOP;
 END LOOP;
 FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE (n.nspname='snap_relaunch' AND p.proname IN ('original_intake_writes_enabled_v1','original_intake_actor_v1','original_intake_result_v1','original_intake_immutable_v1','original_intake_job_guard_v1'))
  OR (n.nspname='public' AND p.proname IN ('fn_reserve_original_intake_v1','fn_lookup_original_intake_v1','fn_read_original_intake_v1','fn_revoke_original_intake_v1','fn_original_intake_transport_read_v1','fn_verify_original_intake_v1','fn_original_intake_delete_guard_v1')) LOOP
  FOR g IN SELECT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=f AND a.grantee<>p.proowner LOOP
   role_name:=CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(g.grantee)) END;
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',f,role_name);
  END LOOP;
 END LOOP;
END $private$;
GRANT EXECUTE ON FUNCTION public.fn_reserve_original_intake_v1(uuid,text,bigint,text),public.fn_lookup_original_intake_v1(text,bigint),public.fn_read_original_intake_v1(uuid),public.fn_revoke_original_intake_v1(uuid),public.fn_original_intake_delete_guard_v1(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_original_intake_transport_read_v1(uuid,uuid),public.fn_verify_original_intake_v1(uuid,uuid,text,bigint,text) TO service_role;

