NS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n IF TG_OP='INSERT' THEN\n  IF starts_with(NEW.storage_path,'_snap_originals/v1/') AND NOT EXISTS(\n   SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 r WHERE r.job_id=NEW.id AND r.owner_id=NEW.user_id\n    AND r.original_filename=NEW.filename AND r.original_bytes=NEW.file_size AND r.object_key=NEW.storage_path) THEN\n   RAISE EXCEPTION 'original_intake_reserved_path' USING ERRCODE='42501';\n  END IF;\n  RETURN NEW;\n END IF;\n IF TG_OP='UPDATE' AND starts_with(NEW.storage_path,'_snap_originals/v1/') AND NEW.storage_path IS DISTINCT FROM OLD.storage_path THEN\n  RAISE EXCEPTION 'original_intake_identity_immutable' USING ERRCODE='55000';END IF;\n IF starts_with(OLD.storage_path,'_snap_originals/v1/') OR EXISTS(SELECT 1 FROM snap_relaunch.original_intake_reservations_v1 WHERE job_id=OLD.id) THEN\n  IF TG_OP='DELETE' OR NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id\n   OR NEW.storage_path IS DISTINCT FROM OLD.storage_path OR NEW.filename IS DISTINCT FROM OLD.filename\n   OR NEW.file_size IS DISTINCT FROM OLD.file_size THEN RAISE EXCEPTION 'original_intake_identity_immutable' USING ERRCODE='55000';END IF;\n  IF current_setting('role',true) IN ('anon','authenticated') THEN\n   RAISE EXCEPTION 'original_intake_processing_held' USING ERRCODE='55000';END IF;\n END IF;\n IF TG_OP='DELETE' THEN RETURN OLD;END IF;\n RETURN NEW;\nEND$function$\n"},{"name":"source_bindings_immutable","table":"upload_source_bindings","enabled":"O","definition":"CREATE TRIGGER source_bindings_immutable BEFORE DELETE OR UPDATE ON public.upload_source_bindings FOR EACH ROW EXECUTE FUNCTION protect_bound_source_review_v1()","function_definition":"CREATE OR REPLACE FUNCTION public.protect_bound_source_review_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF TG_TABLE_NAME='upload_source_bindings' THEN\n    RAISE EXCEPTION 'Source bindings are fixed; prepare a separately reviewed job';\n  END IF;\n  IF OLD.source_semantics->>'source_key' IN ('syracuse_code_violations_v2','chicago_22u3_xenr') THEN\n    RAISE EXCEPTION 'Source review staging is immutable; prepare a new observation or revision';\n  END IF;\n  IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND $function$\n"},{"name":"protect_objects_delete","table":"storage.objects","enabled":"O","definition":"CREATE TRIGGER protect_objects_delete BEFORE DELETE ON storage.objects FOR EACH STATEMENT EXECUTE FUNCTION storage.protect_delete()","function_definition":"CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n"},{"name":"update_objects_updated_at","table":"storage.objects","enabled":"O","definition":"CREATE TRIGGER update_objects_updated_at BEFORE UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.update_updated_at_column()","function_definition":"CREATE OR REPLACE FUNCTION storage.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n$function$\n"}],"relations":[{"acl":"{supabase_storage_admin=a*r*w*d*D*x*t*m*/supabase_storage_admin,anon=arwdDxtm/supabase_storage_admin,authenticated=arwdDxtm/supabase_storage_admin,service_role=arwdDxtm/supabase_storage_admin,postgres=a*r*w*d*D*x*t*m*/supabase_storage_admin,sandbox_exec_ojyxblegxpdgaqiscxpz=ar/postgres,sandbox_exec=ar/postgres}","rls":true,"name":"buckets","owner":"supab