ansport_read_v1","owner":"postgres","schema":"public"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","md5":"cd90921b7b165976804abf5ea9557da4","args":"p_owner uuid, p_job uuid, p_sha256 text, p_bytes bigint, p_object_key text","name":"fn_verify_original_intake_v1","owner":"postgres","schema":"public"}],"new_relations":[{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"original_intake_requests_v1","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_requests_v1_pkey","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"original_intake_reservations_v1","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_reservations_v1_object_key_key","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_reservations_v1_owner_id_original_sha256_key","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_reservations_v1_pkey","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"original_intake_revocations_v1","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_revocations_v1_pkey","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_revocations_v1_revocation_id_key","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"original_intake_verifications_v1","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_verifications_v1_pkey","owner":"postgres"},{"acl":"{postgres=arwdDxtm/postgres}","rls":false,"name":"original_intake_verifications_v1_verification_id_key","owner":"postgres"}]}$expected$::jsonb;

 a:=a-ARRAY['observed_at','current_user','session_user','search_path','server_version','default_acl'];
 e:=e-ARRAY['observed_at','current_user','session_user','search_path','server_version','default_acl'];
 IF a ? 'roles' THEN
  a:=jsonb_set(a,'{roles}',coalesce((SELECT jsonb_agg(item) FROM jsonb_array_elements(a->'roles') q(item) WHERE item->>'name' IN ('anon','authenticated','service_role')),'[]'));
 END IF;
 IF a ? 'memberships' THEN
  a:=jsonb_set(a,'{memberships}',coalesce((SELECT jsonb_agg(item) FROM jsonb_array_elements(coalesce(nullif(a->'memberships','null'::jsonb),'[]')) q(item) WHERE item->>'member' IN ('anon','authenticated','service_role')),'[]'));
 END IF;
 -- Only array ordering is normalized; within-table column order and enum order stay pinned.
 FOREACH side IN ARRAY ARRAY['actual','expected'] LOOP
  target:=CASE WHEN side='actual' THEN a ELSE e END;
  FOR k,v IN SELECT key,value FROM jsonb_each(target) LOOP
   IF jsonb_typeof(v)='array' AND k<>'enum_labels' THEN
    IF k IN ('columns','generated_columns') THEN
     SELECT coalesce(jsonb_agg(item ORDER BY coalesce(item->>'table',''),ordinal),'[]') INTO sorted FROM jsonb_array_elements(v) WITH ORDINALITY q(item,ordinal);
    ELSE
     SELECT coalesce(jsonb_agg(item ORDER BY item),'[]') INTO sorted FROM jsonb_array_elements(v) item;
    END IF;
    target:=jsonb_set(target,ARRAY[k],sorted);
   END IF;
  END LOOP;
  IF side='actual' THEN a:=target;ELSE e:=target;END IF;
 END LOOP;
 IF a IS DISTINCT FROM e THEN
  SELECT key INTO k FROM jsonb_each(e) WHERE a->key IS DISTINCT FROM e->key ORDER BY key LIMIT 1;
  RAISE EXCEPTION 'original_intake_catalog_drift:%:%:%','after','base',k USING ERRCODE='55000';END IF;
